  app.get('/api/categories/*splat', (req, res) => {
    const path = req.params.splat.join('/')
    if (!categories.includes(path)) {
      return res.status(404).json({ error: 'not_found' })
    }
    const inCategory = products.filter(
      (product) => product.category === path || product.category.startsWith(`${path}/`),
    )
    res.json({ path, products: inCategory })
  })

  // One product as JSON, or as CSV when the SKU segment ends in `.csv`.
  app.get('/api/products/:sku', (req, res) => {
    const wantsCsv = req.params.sku.endsWith('.csv')
    const sku = wantsCsv ? req.params.sku.slice(0, -'.csv'.length) : req.params.sku
    const product = products.find((item) => item.sku === sku)
    if (!product) {
      return res.status(404).json({ error: 'not_found' })
    }
    if (!wantsCsv) {
      return res.json(product)
    }
    const row = [product.sku, product.name, product.price].map(csvField).join(',')
    res.type('text/csv').send(`sku,name,price\n${row}\n`)
  })

